#[derive(Clone, Debug, PartialEq, Eq)]
pub enum TreeOp {
    /// insert a node
    Create { id: u32, parent: u32, index: u32, kind: NodeKind, props: Vec<Prop> },
    /// change some props
    Set { id: u32, props: Vec<Prop> },
    Move { id: u32, parent: u32, index: u32 },
    /// and its children
    Remove { id: u32 },
}

impl TreeOp {
    pub fn tag(&self) -> u8 {
        match self {
            TreeOp::Create { .. } => 0,
            TreeOp::Set { .. } => 1,
            TreeOp::Move { .. } => 2,
            TreeOp::Remove { .. } => 3,
        }
    }
    pub fn name(&self) -> &'static str {
        match self {
            TreeOp::Create { .. } => "Create",
            TreeOp::Set { .. } => "Set",
            TreeOp::Move { .. } => "Move",
            TreeOp::Remove { .. } => "Remove",
        }
    }
    pub fn enc(&self, w: &mut Writer) {
        w.u8(self.tag());
        match self {
            TreeOp::Create { id, parent, index, kind, props } => {
                w.u32(*id);
                w.u32(*parent);
                w.u32(*index);
                w.u8((kind).code());
                w.u32((props).len() as u32);
                for x0 in (props).iter() {
                    (x0).enc(w);
                }
            }
            TreeOp::Set { id, props } => {
                w.u32(*id);
                w.u32((props).len() as u32);
                for x0 in (props).iter() {
                    (x0).enc(w);
                }
            }
            TreeOp::Move { id, parent, index } => {
                w.u32(*id);
                w.u32(*parent);
                w.u32(*index);
            }
            TreeOp::Remove { id } => {
                w.u32(*id);
            }
        }
    }
    pub fn dec(r: &mut Reader) -> Result<Self, DecodeError> {
        Ok(match r.u8()? {
            0 => {
                let id = { let v = r.u32()?; if v < 1 { return Err(DecodeError::OutOfRange("TreeOp.Create.id")); } v };
                let parent = r.u32()?;
                let index = r.u32()?;
                let kind = NodeKind::from_code(r.u8()?).ok_or(DecodeError::BadEnum("TreeOp.Create.kind"))?;
                let props = { let n0 = r.count(32, 2, "TreeOp.Create.props")?; let mut v0 = Vec::with_capacity(n0); for _ in 0..n0 { v0.push(Prop::dec(r)?); } for i in 1..v0.len() { if v0[i - 1].tag() >= v0[i].tag() { return Err(DecodeError::Unsorted("TreeOp.Create.props")); } } v0 };
                for p in props.iter() {
                    if !node_allows(kind, p.tag()) {
                        return Err(DecodeError::PropNotAllowed("TreeOp.Create.props"));
                    }
                }
                TreeOp::Create { id, parent, index, kind, props }
            }
            1 => {
                let id = { let v = r.u32()?; if v < 1 { return Err(DecodeError::OutOfRange("TreeOp.Set.id")); } v };
                let props = { let n0 = r.count(32, 2, "TreeOp.Set.props")?; let mut v0 = Vec::with_capacity(n0); for _ in 0..n0 { v0.push(Prop::dec(r)?); } for i in 1..v0.len() { if v0[i - 1].tag() >= v0[i].tag() { return Err(DecodeError::Unsorted("TreeOp.Set.props")); } } v0 };
                TreeOp::Set { id, props }
            }
            2 => {
                let id = { let v = r.u32()?; if v < 1 { return Err(DecodeError::OutOfRange("TreeOp.Move.id")); } v };
                let parent = r.u32()?;
                let index = r.u32()?;
                TreeOp::Move { id, parent, index }
            }
            3 => {
                let id = { let v = r.u32()?; if v < 1 { return Err(DecodeError::OutOfRange("TreeOp.Remove.id")); } v };
                TreeOp::Remove { id }
            }
            _ => return Err(DecodeError::BadEnum("TreeOp")),
        })
    }
    pub fn json(&self, o: &mut String) {
        match self {
            TreeOp::Create { id, parent, index, kind, props } => {
                o.push_str("{\"type\":\"Create\"");
                o.push_str(",\"id\":");
                json_u(o, *id as u64);
                o.push_str(",\"parent\":");
                json_u(o, *parent as u64);
                o.push_str(",\"index\":");
                json_u(o, *index as u64);
                o.push_str(",\"kind\":");
                json_str(o, (kind).name());
                o.push_str(",\"props\":");
                o.push('[');
                for (i0, x0) in (props).iter().enumerate() {
                    if i0 > 0 { o.push(','); }
                    (x0).json(o);
                }
                o.push(']');
                o.push('}');
            }
            TreeOp::Set { id, props } => {
                o.push_str("{\"type\":\"Set\"");
                o.push_str(",\"id\":");
                json_u(o, *id as u64);
                o.push_str(",\"props\":");
                o.push('[');
                for (i0, x0) in (props).iter().enumerate() {
                    if i0 > 0 { o.push(','); }
                    (x0).json(o);
                }
                o.push(']');
                o.push('}');
            }
            TreeOp::Move { id, parent, index } => {
                o.push_str("{\"type\":\"Move\"");
                o.push_str(",\"id\":");
                json_u(o, *id as u64);
                o.push_str(",\"parent\":");
                json_u(o, *parent as u64);
                o.push_str(",\"index\":");
                json_u(o, *index as u64);
                o.push('}');
            }
            TreeOp::Remove { id } => {
                o.push_str("{\"type\":\"Remove\"");
                o.push_str(",\"id\":");
                json_u(o, *id as u64);
                o.push('}');
            }
        }
    }
}

/// Whether a node of `kind` accepts the prop with tag `tag` (§6 table).
pub fn node_allows(kind: NodeKind, tag: u8) -> bool {
    match kind {
        NodeKind::Group => matches!(tag, 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 | 29 | 30 | 31 | 32 | 33 | 34),
        NodeKind::Rect => matches!(tag, 1 | 2 | 3 | 4 | 9 | 10 | 11 | 12 | 8 | 23 | 24 | 26 | 27 | 34 | 36),
        NodeKind::Text => matches!(tag, 1 | 2 | 13 | 14 | 15 | 16 | 8 | 25 | 28 | 35),
        NodeKind::Image => matches!(tag, 1 | 2 | 3 | 4 | 17 | 18 | 19 | 20 | 8),
        NodeKind::Canvas => matches!(tag, 1 | 2 | 3 | 4 | 17 | 7 | 8),
        NodeKind::Line => matches!(tag, 21 | 22 | 16 | 8),
    }
}

