    pub(crate) fn dec_body(opcode: u16, r: &mut Reader) -> Result<Message, DecodeError> {
        Ok(match opcode {
            0x0001 => Message::Hello(Hello::dec(r)?),
            0x0002 => Message::Welcome(Welcome::dec(r)?),
            0x0003 => Message::Error(Error::dec(r)?),
            0x0100 => Message::SurfaceCreate(SurfaceCreate::dec(r)?),
            0x0101 => Message::SurfaceDestroy(SurfaceDestroy::dec(r)?),
            0x0102 => Message::SurfaceSetTitle(SurfaceSetTitle::dec(r)?),
            0x0103 => Message::SurfaceSetHints(SurfaceSetHints::dec(r)?),
            0x0104 => Message::SurfaceResize(SurfaceResize::dec(r)?),
            0x0105 => Message::Configure(Configure::dec(r)?),
            0x0106 => Message::AckConfigure(AckConfigure::dec(r)?),
            0x0107 => Message::Commit(Commit::dec(r)?),
            0x0108 => Message::RequestFrame(RequestFrame::dec(r)?),
            0x0109 => Message::Frame(Frame::dec(r)?),
            0x010c => Message::CommitAt(CommitAt::dec(r)?),
            0x010d => Message::QueueFlush(QueueFlush::dec(r)?),
            0x010e => Message::SurfaceSetContent(SurfaceSetContent::dec(r)?),
            0x010f => Message::QueueLimits(QueueLimits::dec(r)?),
            0x010a => Message::CloseRequested(CloseRequested::dec(r)?),
            0x010b => Message::PopupDone(PopupDone::dec(r)?),
            0x0200 => Message::TreeOps(TreeOps::dec(r)?),
            0x0210 => Message::ResourceCreate(ResourceCreate::dec(r)?),
            0x0211 => Message::ResourceDestroy(ResourceDestroy::dec(r)?),
            0x0300 => Message::Pointer(Pointer::dec(r)?),
            0x0301 => Message::Key(Key::dec(r)?),
            0x0302 => Message::Text(Text::dec(r)?),
            0x0303 => Message::Focus(Focus::dec(r)?),
            0x0304 => Message::Hotkey(Hotkey::dec(r)?),
            0x0305 => Message::Chord(Chord::dec(r)?),
            0x0310 => Message::HotkeyClaim(HotkeyClaim::dec(r)?),
            0x0311 => Message::PointerLock(PointerLock::dec(r)?),
            0x0313 => Message::Scrolled(Scrolled::dec(r)?),
            0x0312 => Message::PointerLockChanged(PointerLockChanged::dec(r)?),
            0x0400 => Message::WindowOpened(WindowOpened::dec(r)?),
            0x0401 => Message::WindowChanged(WindowChanged::dec(r)?),
            0x0402 => Message::WindowClosed(WindowClosed::dec(r)?),
            0x0403 => Message::WindowRequest(WindowRequest::dec(r)?),
            0x0404 => Message::DisplayChanged(DisplayChanged::dec(r)?),
            0x0410 => Message::Place(Place::dec(r)?),
            0x0411 => Message::Stack(Stack::dec(r)?),
            0x0412 => Message::FocusWindow(FocusWindow::dec(r)?),
            0x0413 => Message::SetVisible(SetVisible::dec(r)?),
            0x0414 => Message::SetOpacity(SetOpacity::dec(r)?),
            0x0415 => Message::BindChord(BindChord::dec(r)?),
            0x0416 => Message::CloseWindow(CloseWindow::dec(r)?),
            0x0417 => Message::Launch(Launch::dec(r)?),
            0x0418 => Message::SetTheme(SetTheme::dec(r)?),
            0x0419 => Message::ThemeChanged(ThemeChanged::dec(r)?),
            0x0500 => Message::PermissionPrompt(PermissionPrompt::dec(r)?),
            0x0501 => Message::AnswerPermission(AnswerPermission::dec(r)?),
            0x0510 => Message::ClipboardSet(ClipboardSet::dec(r)?),
            0x0511 => Message::ClipboardRequest(ClipboardRequest::dec(r)?),
            0x0512 => Message::ClipboardData(ClipboardData::dec(r)?),
            0x0520 => Message::Notify(Notify::dec(r)?),
            0x0521 => Message::NotificationAction(NotificationAction::dec(r)?),
            0x0522 => Message::NotificationPosted(NotificationPosted::dec(r)?),
            0x0523 => Message::NotificationInvoke(NotificationInvoke::dec(r)?),
            0x0530 => Message::PickFile(PickFile::dec(r)?),
            0x0531 => Message::FilePicked(FilePicked::dec(r)?),
            0x0532 => Message::Open(Open::dec(r)?),
            0x0533 => Message::OpenFile(OpenFile::dec(r)?),
            0x0600 => Message::WillSuspend(WillSuspend::dec(r)?),
            0x0601 => Message::SaveState(SaveState::dec(r)?),
            0x0602 => Message::Restore(Restore::dec(r)?),
            0x0603 => Message::BackgroundDone(BackgroundDone::dec(r)?),
            _ => return Err(DecodeError::UnknownOpcode(opcode)),
        })
    }
    /// Whether `opcode` names a message of this protocol version.
    pub fn is_known(opcode: u16) -> bool {
        matches!(opcode, 0x0001 | 0x0002 | 0x0003 | 0x0100 | 0x0101 | 0x0102 | 0x0103 | 0x0104 | 0x0105 | 0x0106 | 0x0107 | 0x0108 | 0x0109 | 0x010c | 0x010d | 0x010e | 0x010f | 0x010a | 0x010b | 0x0200 | 0x0210 | 0x0211 | 0x0300 | 0x0301 | 0x0302 | 0x0303 | 0x0304 | 0x0305 | 0x0310 | 0x0311 | 0x0313 | 0x0312 | 0x0400 | 0x0401 | 0x0402 | 0x0403 | 0x0404 | 0x0410 | 0x0411 | 0x0412 | 0x0413 | 0x0414 | 0x0415 | 0x0416 | 0x0417 | 0x0418 | 0x0419 | 0x0500 | 0x0501 | 0x0510 | 0x0511 | 0x0512 | 0x0520 | 0x0521 | 0x0522 | 0x0523 | 0x0530 | 0x0531 | 0x0532 | 0x0533 | 0x0600 | 0x0601 | 0x0602 | 0x0603)
    }
